; miser module, segment E800
; re-assemblable NASM source generated by tools/mkasm.py from the labelled analysis (labels are best guesses)
; nasm -f bin -i src/ %s -o module.bin  reproduces the ROM module byte for byte
        bits 16
        org 0
%include "vars.inc"          ; RAM variable / structure offsets (generated from labels/vars.json)


; 55AA option ROM signature, size 30h*512 = 24 KB. Lives at E800:0000 at runtime (system BIOS far-calls E800:0010 etc).
rom_header:
; [data] option ROM header
        db 0x55, 0xAA, 0x30 ; 0000 U.0

; Option ROM init entry: RETF - nothing to do at scan time
init_stub:
        retf                                     ; 0003

; 'PhoenixMISER' identification string
miser_signature:
; [data] signature
; [data] string
        db 0x50, 0x68, 0x6F, 0x65, 0x6E, 0x69, 0x78, 0x4D, 0x49, 0x53, 0x45, 0x52 ; 0004 PhoenixMISER

; Far-callable entry table (each is call near ; retf). Called from system BIOS at F000:98F9 and jumped to from F000:5940 (POST start).
api_entry_10:
        call miser_post_hook                     ; 0010
        retf                                     ; 0013
        times 8 db 0x00                     ; 0014 fill

; jmp near
api_entry_1C:
        db 0xE9, 0x32, 0x19                      ; 001C  jmp get_api_far_ptr
        db 0x00, 0x00, 0x00, 0x00, 0x00 ; 001F .....

; RETF stub; system BIOS far-jumps here from F000:5B01
api_entry_24:
        retf                                     ; 0024
        db 0x00, 0x00, 0x00 ; 0025 ...

; jmp near. System BIOS INT 15h handler far-jumps here when AH=53h (APM) - F000:BC70
api_entry_28_apm:
        jmp near apm_int15_53_handler            ; 0028
        db 0x00 ; 002B .

; API 2Ch: jmp pm_record_service (SETUP/system BIOS record accessors, AH = sub-function, AL = record).
api_entry_2C:
        db 0xE8, 0xA8, 0x18                      ; 002C  call pm_record_service
        retf                                     ; 002F

; API 30h: show the POWER METER overlay (system BIOS hot key Ctrl+Alt+F8 / Fn code 6Ah). Target show_power_meter.
api_entry_30_power_meter:
        call show_power_meter                    ; 0030
        retf                                     ; 0033

; Called via far pointer at F000:7B57 (SS:SP reset to 0000:FFFE first)
api_entry_34:
        call os_environment_check                ; 0034
        retf                                     ; 0037

; API 38h: returns AX=DF00h (MISER signature/RAM segment); used by the system BIOS hot-key handlers as a presence check.
api_entry_38_presence:
        call miser_presence_signature            ; 0038
        retf                                     ; 003B
        db 0x00, 0x00, 0x00, 0x00 ; 003C ....

; API 40h: jmp query_state_34 (ZF = module initialised).
api_entry_40:
        db 0xE8, 0x4F, 0x17                      ; 0040  call query_state_34
        retf                                     ; 0043
        db 0x00, 0x00, 0x00, 0x00 ; 0044 ....

; Called from system BIOS F000:6CF0
api_entry_48:
        db 0xE8, 0x59, 0x17                      ; 0048  call miser_ram_init
        retf                                     ; 004B
        db 0x00, 0x00, 0x00, 0x00 ; 004C ....

; Developer credits: team leader, motherboard, power, sound, BIOS engineers.
credits_string:
; [data] string
        db 0x2A, 0x2A, 0x20, 0x54, 0x65, 0x61, 0x6D, 0x20, 0x4C, 0x65, 0x61, 0x64, 0x65, 0x72, 0x3A, 0x41 ; 0050 ** Team Leader:A
        db 0x6C, 0x62, 0x65, 0x72, 0x74, 0x20, 0x43, 0x68, 0x65, 0x6E, 0x7C, 0x4D, 0x42, 0x3A, 0x41, 0x6C ; 0060 lbert Chen|MB:Al
        db 0x65, 0x78, 0x20, 0x4C, 0x69, 0x6E, 0x2F, 0x4B, 0x65, 0x76, 0x69, 0x6E, 0x20, 0x48, 0x75, 0x61 ; 0070 ex Lin/Kevin Hua
        db 0x6E, 0x67, 0x2F, 0x4D, 0x61, 0x72, 0x6B, 0x20, 0x4B, 0x75, 0x7C, 0x50, 0x6F, 0x77, 0x65, 0x72 ; 0080 ng/Mark Ku|Power
        db 0x3A, 0x4B, 0x2E, 0x20, 0x4C, 0x2E, 0x20, 0x57, 0x75, 0x7C, 0x53, 0x6F, 0x75, 0x6E, 0x64, 0x3A ; 0090 :K. L. Wu|Sound:
        db 0x59, 0x65, 0x6E, 0x20, 0x59, 0x6F, 0x6E, 0x67, 0x20, 0x48, 0x77, 0x61, 0x6E, 0x67, 0x7C, 0x42 ; 00A0 Yen Yong Hwang|B
        db 0x49, 0x4F, 0x53, 0x3A, 0x41, 0x74, 0x6C, 0x61, 0x73, 0x20, 0x48, 0x75, 0x61, 0x6E, 0x67, 0x20 ; 00B0 IOS:Atlas Huang 
        db 0x2A, 0x2A ; 00C0 **

; DC00:000C := 0100h (APM flags: connected bit only), DC00:000E := 0 (battery-low counter).
pm_flags_reset:
        mov word [0xc], 0x100                    ; 00C2
        mov byte [0xe], 0                        ; 00C8
        ret                                      ; 00CD

; API 28h. DS=DC00; sub_00F2 implements INT 15h AH=53h (APM 1.x) functions; RETF 2 discards caller flags like an interrupt return.
apm_int15_53_handler:
        push ds                                  ; 00CE
        push 0xdc00                              ; 00CF
        pop ds                                   ; 00D2
        call apm_dispatch                        ; 00D3
        pop ds                                   ; 00D6
        retf 2                                   ; 00D7

; 12 near pointers for INT 15h AH=53h AL=00h..0Bh (APM 1.0/1.1 functions). Called from the APM handler at 0139.
apm_function_table:
; [data] table apm_function_table (12 near ptrs)
        db 0x5A, 0x01, 0x82, 0x01, 0xBF, 0x01, 0x0B, 0x02, 0x5C, 0x02, 0x7F, 0x02, 0x95, 0x02, 0xAB, 0x02 ; 00DA Z.......\.......
        db 0x02, 0x03, 0x5E, 0x03, 0x89, 0x03, 0x0E, 0x04 ; 00EA ..^.....

; INT 15h AH=53h body: AL>0Bh -> CF=1 (unsupported); else chipset reg 0Eh:=3E18h, open private RAM, call apm_function_table[AL], close RAM, chipset reg 0Eh:=3E10h.
apm_dispatch:
        pushf                                    ; 00F2
        cli                                      ; 00F3
        push ax                                  ; 00F4
        push si                                  ; 00F5
        push ebp                                 ; 00F6
        db 0x66, 0x8B, 0xEC                      ; 00F8  mov ebp, esp
        and ebp, 0xffff                          ; 00FB
        jmp short loc_010D                       ; 0102

; Body of apm_dispatch (also reached from the far entries apm_dispatch_retf32 / apm_dispatch_retf): sets CF in the caller's flags for AL > 0Bh, else chipset reg 0Eh := 3E18h, open private RAM, call apm_function_table[AL], close, reg 0Eh := 3E10h.
apm_dispatch_body:
        pushf                                    ; 0104
        cli                                      ; 0105
        push ax                                  ; 0106
        push si                                  ; 0107
        push ebp                                 ; 0108
        db 0x66, 0x8B, 0xEC                      ; 010A  mov ebp, esp

loc_010D:
        or byte [ebp + 8], 1                     ; 010D
        cmp al, 0xb                              ; 0112
        ja short loc_0154                        ; 0114
        and byte [ebp + 8], 0xfe                 ; 0116
        push ax                                  ; 011B
        push bx                                  ; 011C
        push cx                                  ; 011D
        push dx                                  ; 011E
        pushf                                    ; 011F
        mov ax, 0xe                              ; 0120
        mov bx, 0x3e18                           ; 0123
        call chipset_reg_write                   ; 0126
        popf                                     ; 0129
        pop dx                                   ; 012A
        pop cx                                   ; 012B
        pop bx                                   ; 012C
        pop ax                                   ; 012D
        call open_private_ram                    ; 012E
        db 0x8B, 0xF0                            ; 0131  mov si, ax
        and si, 0xff                             ; 0133
        shl si, 1                                ; 0137
        call word [cs:si + 0xda]                 ; 0139  indirect call
        call close_private_ram                   ; 013E
        push ax                                  ; 0141
        push bx                                  ; 0142
        push cx                                  ; 0143
        push dx                                  ; 0144
        pushf                                    ; 0145
        mov ax, 0xe                              ; 0146
        mov bx, 0x3e10                           ; 0149
        call chipset_reg_write                   ; 014C
        popf                                     ; 014F
        pop dx                                   ; 0150
        pop cx                                   ; 0151
        pop bx                                   ; 0152
        pop ax                                   ; 0153

loc_0154:
        pop ebp                                  ; 0154
        pop si                                   ; 0156
        pop ax                                   ; 0157
        popf                                     ; 0158
        ret                                      ; 0159

apm_00_installation_check:
        db 0x0B, 0xDB                            ; 015A  or bx, bx
        jne near apm_err_invalid_device          ; 015C
        mov bx, 0x504d                           ; 0160
        mov cx, 7                                ; 0163
        test word [0xc], 0x100                   ; 0166
        jne short loc_0171                       ; 016C
        or cx, 8                                 ; 016E

loc_0171:
        mov word [bp + 6], 0x100                 ; 0171
        push ax                                  ; 0176
        push cx                                  ; 0177
        mov al, 1                                ; 0178
        out 0x80, al                             ; 017A  port 80h: POST diagnostic code
        call pm_event_notify                     ; 017C
        pop cx                                   ; 017F
        pop ax                                   ; 0180
        ret                                      ; 0181

apm_01_connect_real_mode:
        cmp bx, 0                                ; 0182
        jne near apm_err_invalid_device          ; 0185
        test word [0xc], 0x80                    ; 0189
        jne near loc_048D                        ; 018F
        test word [0xc], 0x20                    ; 0193
        jne near loc_0495                        ; 0199
        test word [0xc], 0x40                    ; 019D
        jne near loc_049D                        ; 01A3
        and word [0xc], 0x100                    ; 01A7
        or word [0xc], 0x80                      ; 01AD
        push ax                                  ; 01B3
        push cx                                  ; 01B4
        mov al, 0x11                             ; 01B5
        out 0x80, al                             ; 01B7  port 80h: POST diagnostic code
        call pm_event_notify                     ; 01B9
        pop cx                                   ; 01BC
        pop ax                                   ; 01BD
