        jne near apm_err_invalid_device          ; 01C2
        test word [0xc], 0x40                    ; 01C6
        jne near loc_049D                        ; 01CC
        test word [0xc], 0x20                    ; 01D0
        jne near loc_0495                        ; 01D6
        test word [0xc], 0x80                    ; 01DA
        jne near loc_048D                        ; 01E0
        and word [0xc], 0x100                    ; 01E4
        or word [0xc], 0x80                      ; 01EA
        or word [0xc], 0x20                      ; 01F0
        mov word [ebp + 6], cs                   ; 01F5
        mov bx, 0x4e5                            ; 01F9  -> apm_pm16_entry_thunk
        mov cx, 0xdc00                           ; 01FC
        push ax                                  ; 01FF
        push cx                                  ; 0200
        mov al, 0x21                             ; 0201
        out 0x80, al                             ; 0203  port 80h: POST diagnostic code
        call pm_event_notify                     ; 0205
