        jne near apm_err_invalid_device          ; 020E
        test word [0xc], 0x40                    ; 0212
        jne near loc_049D                        ; 0218
        test word [0xc], 0x20                    ; 021C
        jne near loc_0495                        ; 0222
        test word [0xc], 0x80                    ; 0226
        jne near loc_048D                        ; 022C
        and word [0xc], 0x100                    ; 0230
