        je near apm_err_disabled                 ; 0269
        and word [0xc], 0x100                    ; 026D
        push ax                                  ; 0273
        push cx                                  ; 0274
        mov al, 0x41                             ; 0275
        out 0x80, al                             ; 0277  port 80h: POST diagnostic code
        call pm_event_notify                     ; 0279
        pop cx                                   ; 027C
        pop ax                                   ; 027D
