; BX must be 1 (all devices), CX = state <= 4. Requires DC00:000C bit 8 (connected) and bit 7 (PM enabled). Only CX=2 (suspend) is implemented: POST 71h/72h notifications (pm_event_notify), enter_suspend (sub_213D), flag bit 2 set, POST 70h. Other states -> error 04A9.
apm_07_set_power_state:
        cmp bx, 1                                ; 02AB
        jne near apm_err_invalid_device          ; 02AE
        cmp cx, 4                                ; 02B2
        ja near apm_err_param                    ; 02B5
        test word [0xc], 0x100                   ; 02B9
        je near apm_err_not_connected            ; 02BF
        test word [0xc], 0x80                    ; 02C3
        je near apm_err_disabled                 ; 02C9
        push ax                                  ; 02CD
        push cx                                  ; 02CE
        mov al, 0x71                             ; 02CF
        out 0x80, al                             ; 02D1  port 80h: POST diagnostic code
        call pm_event_notify                     ; 02D3
        pop cx                                   ; 02D6
        pop ax                                   ; 02D7
        cmp cx, 2                                ; 02D8
        jne near apm_err_param                   ; 02DB
        push ax                                  ; 02DF
        push cx                                  ; 02E0
        mov al, 0x72                             ; 02E1
        out 0x80, al                             ; 02E3  port 80h: POST diagnostic code
        call pm_event_notify                     ; 02E5
        pop cx                                   ; 02E8
        pop ax                                   ; 02E9
        db 0xE8, 0x50, 0x1E                      ; 02EA  call enter_suspend
        jb near loc_04AD                         ; 02ED
        or word [0xc], 4                         ; 02F1
        push ax                                  ; 02F6
        push cx                                  ; 02F7
        mov al, 0x70                             ; 02F8
        out 0x80, al                             ; 02FA  port 80h: POST diagnostic code
        call pm_event_notify                     ; 02FC
        pop cx                                   ; 02FF
        pop ax                                   ; 0300
        ret                                      ; 0301

apm_08_enable_disable_pm:
        cmp bx, -1                               ; 0302
        jne near apm_err_invalid_device          ; 0305
        db 0x0A, 0xC9                            ; 0309  or cl, cl
        jne short loc_0333                       ; 030B
        test word [0xc], 0x100                   ; 030D
        je near apm_err_not_connected            ; 0313
        and word [0xc], 0xfeff                   ; 0317
        push ax                                  ; 031D
        push cx                                  ; 031E
        mov al, 0x80                             ; 031F
        out 0x80, al                             ; 0321  port 80h: POST diagnostic code
        call pm_event_notify                     ; 0323
        pop cx                                   ; 0326
        pop ax                                   ; 0327
        push ax                                  ; 0328
        mov al, 0                                ; 0329
        mov byte [0x10f], al                     ; 032B  miser_ram.pm_level?
        db 0xE8, 0x12, 0x17                      ; 032E  call pm_timeouts_apply
        pop ax                                   ; 0331
        ret                                      ; 0332

loc_0333:
        cmp cl, 1                                ; 0333
        jne near apm_err_param                   ; 0336
        or word [0xc], 0x100                     ; 033A
        push ax                                  ; 0340
        push cx                                  ; 0341
        mov al, 0x81                             ; 0342
        out 0x80, al                             ; 0344  port 80h: POST diagnostic code
        call pm_event_notify                     ; 0346
        pop cx                                   ; 0349
        pop ax                                   ; 034A
        push ax                                  ; 034B
        push bx                                  ; 034C
        mov al, 0x42                             ; 034D
        mov bl, 3                                ; 034F  -> init_stub
        db 0xE8, 0xA3, 0x1C                      ; 0351  call cmos_read_field
        mov byte [0x10f], ah                     ; 0354  miser_ram.pm_level?
