        push ax                                  ; 036B
        push bx                                  ; 036C
        mov al, 0x42                             ; 036D
        mov bl, 3                                ; 036F  -> init_stub
        db 0xE8, 0x83, 0x1C                      ; 0371  call cmos_read_field
        mov byte [0x10f], ah                     ; 0374  miser_ram.pm_level?
        db 0xE8, 0xC8, 0x16                      ; 0378  call pm_timeouts_apply
