; BX must be 1. Returns BH = AC line (chipset reg 1 bit 3 -> 1 online / 0 offline), BL = battery status (FFh unknown when chipset reg 12h bit 0 says no battery; 2 = low when reg 0 bits 12-13 set; 1 = low when percentage <= 25; else 0 = high), CL = battery life % = ((port 1FFh & 3Fh) x 80) / 51.
apm_0A_get_power_status:
        cmp bx, 1                                ; 0389
        jne near apm_err_invalid_device          ; 038C
        push ax                                  ; 0390
        push dx                                  ; 0391
        mov bx, 0x1ff                            ; 0392
        mov cl, 0xff                             ; 0395
        push bx                                  ; 0397
        push cx                                  ; 0398
        mov ax, 1                                ; 0399
        mov dx, 8                                ; 039C
        call chipset_reg_test                    ; 039F
        pop cx                                   ; 03A2
        pop bx                                   ; 03A3
        jne near loc_03AA                        ; 03A4
        mov bh, 0                                ; 03A8

loc_03AA:
        push bx                                  ; 03AA
        push cx                                  ; 03AB
        mov ax, 0x12                             ; 03AC
        mov dx, 1                                ; 03AF
        call chipset_reg_test                    ; 03B2
        pop cx                                   ; 03B5
        pop bx                                   ; 03B6
        jne near loc_040B                        ; 03B7
        push bx                                  ; 03BB
        mov ax, 0                                ; 03BC
        call chipset_reg_read                    ; 03BF
        db 0x8B, 0xD3                            ; 03C2  mov dx, bx
        pop bx                                   ; 03C4
        test dh, 0x30                            ; 03C5
        je near loc_03D0                         ; 03C8
        mov bl, 2                                ; 03CC
        jmp short loc_03D2                       ; 03CE

loc_03D0:
        db 0x32, 0xDB                            ; 03D0  xor bl, bl

loc_03D2:
        mov dx, 0x1ff                            ; 03D2
        in al, dx                                ; 03D5
        jmp short loc_03D8                       ; 03D6

loc_03D8:
        jmp short loc_03DA                       ; 03D8

loc_03DA:
        jmp short loc_03DC                       ; 03DA

loc_03DC:
        shl al, 2                                ; 03DC
        db 0x8A, 0xC8                            ; 03DF  mov cl, al
        push ax                                  ; 03E1
        push dx                                  ; 03E2
        db 0x8A, 0xC1                            ; 03E3  mov al, cl
        mov cl, 0x14                             ; 03E5
        mul cl                                   ; 03E7
        mov cl, 0x33                             ; 03E9
        div cl                                   ; 03EB
        db 0x8A, 0xC8                            ; 03ED  mov cl, al
        pop dx                                   ; 03EF
        pop ax                                   ; 03F0
        push bx                                  ; 03F1
        mov ax, 0                                ; 03F2
        call chipset_reg_read                    ; 03F5
        db 0x8B, 0xD3                            ; 03F8  mov dx, bx
        pop bx                                   ; 03FA
        test dh, 0x30                            ; 03FB
        jne near loc_040B                        ; 03FE
        cmp cl, 0x19                             ; 0402
        ja near loc_040B                         ; 0405
        mov bl, 1                                ; 0409

loc_040B:
        pop dx                                   ; 040B
        pop ax                                   ; 040C
        ret                                      ; 040D

; Event word at DC00:000C (bit 7 = PM enabled gate). Battery-low detection: chipset reg 0 bits 12-13 and reg 9 bit 8, debounced 3 times via counter at DC00:000E -> sets event bit 4. Returns BX = 1 standby request, 2 suspend request, 3 normal resume, 4 critical resume, 5 battery low (lowest pending bit, then cleared); POST B1h; no event -> error 04B1.
apm_0B_get_pm_event:
        mov ax, word [0xc]                       ; 040E
        test word [0xc], 0x80                    ; 0411
        je near apm_err_disabled                 ; 0417
        push cx                                  ; 041B
        push dx                                  ; 041C
        push ax                                  ; 041D
        push bx                                  ; 041E
        push dx                                  ; 041F
        and word [0xc], 0xffef                   ; 0420
        mov ax, 0                                ; 0425
        call chipset_reg_read                    ; 0428
        test bh, 0x30                            ; 042B
        je near loc_0458                         ; 042E
        push bx                                  ; 0432
        mov ax, 9                                ; 0433
        call chipset_reg_read                    ; 0436
        db 0x8B, 0xD3                            ; 0439  mov dx, bx
        pop bx                                   ; 043B
        test dh, 1                               ; 043C
        je near loc_0458                         ; 043F
        push ax                                  ; 0443
        mov al, byte [0xe]                       ; 0444
        inc al                                   ; 0447
        mov byte [0xe], al                       ; 0449
        cmp al, 3                                ; 044C
        pop ax                                   ; 044E
        ja near loc_0458                         ; 044F
        or word [0xc], 0x10                      ; 0453

loc_0458:
        pop dx                                   ; 0458
        pop bx                                   ; 0459
        pop ax                                   ; 045A
        mov bx, 1                                ; 045B
        mov dx, 1                                ; 045E
        mov cx, 5                                ; 0461

loc_0464:
        test bx, ax                              ; 0464
        jne short loc_0471                       ; 0466
        shl bx, 1                                ; 0468
        inc dx                                   ; 046A
        loop loc_0464                            ; 046B
        pop dx                                   ; 046D
        pop cx                                   ; 046E
        jmp short apm_err_no_event               ; 046F

loc_0471:
        not bx                                   ; 0471
        and word [0xc], bx                       ; 0473
        db 0x8B, 0xDA                            ; 0477  mov bx, dx
        pop dx                                   ; 0479
        pop cx                                   ; 047A
        push ax                                  ; 047B
        push bx                                  ; 047C
        push cx                                  ; 047D
        mov al, 0xb1                             ; 047E
        out 0x80, al                             ; 0480  port 80h: POST diagnostic code
        call pm_event_notify                     ; 0482
        pop cx                                   ; 0485
        pop bx                                   ; 0486
