; Builds the 15 x 8-byte device/configuration records at DC00:008E from the ROM table config_records (17BD). Each ROM entry: record index, CMOS index, bit mask, handler pointer, N, N encoded values (list A), N raw values (list B). Record layout: +0 current CMOS field (cmos_read_field), +1 N, +2 handler, +4 -> list A, +6 -> list B. Afterwards pm_record_service AH=1 and AH=3 are run for records 0..0Eh, which calls every handler with the current setting.
config_records_init:
        pusha                                    ; 1874
        push es                                  ; 1875
        push ds                                  ; 1876
        pop es                                   ; 1877
        mov di, 0x8e                             ; 1878
        mov cx, 0x78                             ; 187B
        mov al, 0                                ; 187E
        rep stosb                                ; 1880
        mov si, 0x17bd                           ; 1882
        db 0x2E, 0xAC                            ; 1885  lodsb al, byte ptr cs:[si]

loc_1887:
        mov di, 0x8e                             ; 1887
        mov ah, 8                                ; 188A
        mul ah                                   ; 188C
        db 0x03, 0xF8                            ; 188E  add di, ax
        db 0x2E, 0xAD                            ; 1890  lodsw ax, word ptr cs:[si]
        db 0x8A, 0xDC                            ; 1892  mov bl, ah
        db 0xE8, 0x60, 0x07                      ; 1894  call cmos_read_field
        mov byte [di], ah                        ; 1897
        db 0x2E, 0xAD                            ; 1899  lodsw ax, word ptr cs:[si]
        mov word [di + 2], ax                    ; 189B
        db 0x2E, 0xAC                            ; 189E  lodsb al, byte ptr cs:[si]
        mov byte [di + 1], al                    ; 18A0
        mov word [di + 4], si                    ; 18A3
        db 0x32, 0xE4                            ; 18A6  xor ah, ah
        db 0x03, 0xF0                            ; 18A8  add si, ax
        mov word [di + 6], si                    ; 18AA
        db 0x03, 0xF0                            ; 18AD  add si, ax
        db 0x2E, 0xAC                            ; 18AF  lodsb al, byte ptr cs:[si]
        cmp al, 0xff                             ; 18B1
        db 0x75, 0xD2                            ; 18B3  jne loc_1887
        db 0x33, 0xC0                            ; 18B5  xor ax, ax

loc_18B7:
        mov ah, 1                                ; 18B7
        call pm_record_service                   ; 18B9
        mov ah, 3                                ; 18BC  -> init_stub
        call pm_record_service                   ; 18BE
        inc al                                   ; 18C1
        cmp al, 0xf                              ; 18C3
        jb short loc_18B7                        ; 18C5
        db 0xE8, 0x80, 0xFA                      ; 18C7  call open_private_ram
        pop es                                   ; 18CA
        popa                                     ; 18CB
        ret                                      ; 18CC

; 5 near pointers indexed by AH & 0Fh (0..4) - power-management record accessors (called from 190F with DS=DC00).
pm_subfn_dispatch_table:
; [data] table pm_subfn_dispatch_table (5 near ptrs)
        db 0x19, 0x19, 0x1E, 0x19, 0x22, 0x19, 0x38, 0x19, 0x57, 0x19 ; 18CD ....".8.W.

; API 2Ch. AH & 0Fh selects one of 5 record accessors (table 18CD); AH>=5 returns AH=81h/86h error.
pm_record_service:
