        push ds                                  ; 18D8
        push si                                  ; 18D9
        push di                                  ; 18DA
        push ax                                  ; 18DB
        and ah, 0xf                              ; 18DC
        cmp ah, 4                                ; 18DF
        pop ax                                   ; 18E2
        je near pm_subfn_dispatch                ; 18E3
        ja short loc_1914                        ; 18E7
        cmp al, 0xf                              ; 18E9
        jb near pm_subfn_dispatch                ; 18EB
        mov ah, 0x81                             ; 18EF
        jmp short loc_1914                       ; 18F1

; DS := DC00h (MISER private RAM segment), SI := AH*2, DI := 8Eh + AL*8 (per-device record), then call table at 18CD.
pm_subfn_dispatch:
        cli                                      ; 18F3
        cld                                      ; 18F4
        mov si, 0xdc00                           ; 18F5
        mov ds, si                               ; 18F8
        movzx si, ah                             ; 18FA
        db 0x03, 0xF6                            ; 18FD  add si, si
        push ax                                  ; 18FF
        mov di, 0x8e                             ; 1900
        mov ah, 8                                ; 1903
        mul ah                                   ; 1905
        db 0x03, 0xF8                            ; 1907  add di, ax
        pop ax                                   ; 1909
        db 0xE8, 0x3D, 0xFA                      ; 190A  call open_private_ram
        mov ah, 0x80                             ; 190D
        call word [cs:si + 0x18cd]               ; 190F  indirect call

loc_1914:
        pop di                                   ; 1914
        pop si                                   ; 1915
        pop ds                                   ; 1916
        popf                                     ; 1917
        ret                                      ; 1918

pm_subfn_00:
        movzx bx, byte [di + 1]                  ; 1919
        ret                                      ; 191D

pm_subfn_01:
        movzx bx, byte [di]                      ; 191E
        ret                                      ; 1921

pm_subfn_02:
        db 0x0A, 0xFF                            ; 1922  or bh, bh
        jne short loc_1935                       ; 1924
        cmp bl, byte [di + 1]                    ; 1926
        jae short loc_1935                       ; 1929
        mov di, word [di + 4]                    ; 192B
        db 0x03, 0xFB                            ; 192E  add di, bx
        movzx cx, byte [cs:di]                   ; 1930
        ret                                      ; 1934

loc_1935:
        mov ah, 0x82                             ; 1935
        ret                                      ; 1937

pm_subfn_03:
