        jne short loc_194E                       ; 193A
        cmp bl, byte [di + 1]                    ; 193C
        jae short loc_194E                       ; 193F
        mov byte [di], bl                        ; 1941
        add bx, word [di + 6]                    ; 1943
        movzx bx, byte [cs:bx]                   ; 1946
