        call days_in_rest_of_year                ; 3CC8
        db 0x03, 0xF8                            ; 3CCB  add di, ax
        mov bx, word [0x607]                     ; 3CCD  miser_ram.date_snapshot+4?
        call days_between_years                  ; 3CD1
        db 0x03, 0xF8                            ; 3CD4  add di, ax
        db 0x8B, 0xD3                            ; 3CD6  mov dx, bx
        mov bx, word [0x605]                     ; 3CD8  miser_ram.date_snapshot+2?
        mov cx, word [0x603]                     ; 3CDC  miser_ram.date_snapshot?
        call days_left_in_month                  ; 3CE0
        db 0x2B, 0xF8                            ; 3CE3  sub di, ax
        call days_in_rest_of_year                ; 3CE5
        db 0x2B, 0xF8                            ; 3CE8  sub di, ax
        xchg di, ax                              ; 3CEA
        mov byte [0x5f8], al                     ; 3CEB  miser_ram.day_rollover_flag?
        ret                                      ; 3CEE

; 0FFh pad then 31,28,31,30,31,30,31,31,30,31,30,31.
days_per_month:
; [data] days_per_month
        db 0xFF, 0x1F, 0x1C, 0x1F, 0x1E, 0x1F, 0x1E, 0x1F, 0x1F, 0x1E, 0x1F, 0x1E, 0x1F ; 3CEF .............

; days_per_month[BX] - CX (+1 in a leap-year February).
days_left_in_month:
        db 0x32, 0xE4                            ; 3CFC  xor ah, ah
        mov al, byte [cs:bx + 0x3cef]            ; 3CFE
        db 0x2B, 0xC1                            ; 3D03  sub ax, cx
        cmp bx, 2                                ; 3D05
        jne short loc_3D0D                       ; 3D08
        call leap_year_add                       ; 3D0A

loc_3D0D:
        ret                                      ; 3D0D

; Sum of days_per_month for months BX+1..12 (+1 leap day when BX <= 2).
days_in_rest_of_year:
        push bx                                  ; 3D0E
        db 0x33, 0xC0                            ; 3D0F  xor ax, ax

loc_3D11:
        cmp bx, 0xc                              ; 3D11
        je short loc_3D21                        ; 3D14
        inc bx                                   ; 3D16
        add al, byte [cs:bx + 0x3cef]            ; 3D17
        adc ah, 0                                ; 3D1C
        jmp short loc_3D11                       ; 3D1F

loc_3D21:
        pop bx                                   ; 3D21
        cmp bx, 2                                ; 3D22
        ja short loc_3D2A                        ; 3D25
        call leap_year_add                       ; 3D27

loc_3D2A:
        ret                                      ; 3D2A

; 365 per year from DX to BX plus leap days.
days_between_years:
        push dx                                  ; 3D2B
        db 0x33, 0xC0                            ; 3D2C  xor ax, ax

loc_3D2E:
        db 0x3B, 0xD3                            ; 3D2E  cmp dx, bx
        jae short loc_3D3B                       ; 3D30
        inc dx                                   ; 3D32
        call leap_year_add                       ; 3D33
        add ax, 0x16d                            ; 3D36
        jmp short loc_3D2E                       ; 3D39

loc_3D3B:
        pop dx                                   ; 3D3B
        ret                                      ; 3D3C

; AX += 1 when DL & 3 == 0.
leap_year_add:
        test dl, 3                               ; 3D3D
        jne short loc_3D43                       ; 3D40
        inc ax                                   ; 3D42

loc_3D43:
        ret                                      ; 3D43

; Waits for UIP (CMOS 0Ah bit 7) clear, reads CMOS 07h day -> DL, 08h month -> DH, 09h year -> CL, 32h century -> CH (all BCD), re-checks UIP.
rtc_read_date:
        mov al, 0x8a                             ; 3D44
        call cmos_read                           ; 3D46
        test ah, 0x80                            ; 3D49
        jne short rtc_read_date                  ; 3D4C
        mov al, 0x87                             ; 3D4E
        call cmos_read                           ; 3D50
        db 0x8A, 0xD4                            ; 3D53  mov dl, ah
        mov al, 0x88                             ; 3D55
        call cmos_read                           ; 3D57
        db 0x8A, 0xF4                            ; 3D5A  mov dh, ah
        mov al, 0x89                             ; 3D5C
        call cmos_read                           ; 3D5E
        db 0x8A, 0xCC                            ; 3D61  mov cl, ah
        mov al, 0xb2                             ; 3D63
        call cmos_read                           ; 3D65
        db 0x8A, 0xEC                            ; 3D68  mov ch, ah
        mov al, 0x8a                             ; 3D6A
        call cmos_read                           ; 3D6C
        test ah, 0x80                            ; 3D6F
        jne short rtc_read_date                  ; 3D72
        ret                                      ; 3D74

; Waits for UIP clear, reads CMOS 00h/02h/04h seconds/minutes/hours (BCD).
rtc_read_time:
        mov al, 0x8a                             ; 3D75
        call cmos_read                           ; 3D77
        test ah, 0x80                            ; 3D7A
        jne short rtc_read_time                  ; 3D7D
        mov al, 0x80                             ; 3D7F
        call cmos_read                           ; 3D81
        db 0x8A, 0xF4                            ; 3D84  mov dh, ah
        mov al, 0x82                             ; 3D86
        call cmos_read                           ; 3D88
        db 0x8A, 0xCC                            ; 3D8B  mov cl, ah
        mov al, 0x84                             ; 3D8D
        call cmos_read                           ; 3D8F
        db 0x8A, 0xEC                            ; 3D92  mov ch, ah
        mov al, 0x8a                             ; 3D94
        call cmos_read                           ; 3D96
        test ah, 0x80                            ; 3D99
        jne short rtc_read_time                  ; 3D9C
        ret                                      ; 3D9E

; Box records used by the save-to-disk screens: 3D9F/3DB3 frame + counters, 3DC7 saving, 3DDB restoring, 3DEF error, 3E03 done, 3E17 debug dump, 3E2B, 3E3F; then std_error_msg_ids at 3E53.
std_box_records:
; [data] std_box_records + std_error_msg_ids
        db 0x00, 0xB0, 0x01, 0x00, 0x00, 0x00, 0x70, 0x07, 0x07, 0x0F, 0x70, 0x1F, 0x1F, 0x1E, 0x00, 0x00 ; 3D9F ......p...p.....
        db 0x82, 0x41, 0x5E, 0x41, 0x00, 0xB0, 0x0E, 0x00, 0x00, 0x00, 0x70, 0x07, 0x07, 0x0F, 0x70, 0x1F ; 3DAF .A^A......p...p.
        db 0x1F, 0x1E, 0x00, 0x00, 0xE3, 0x41, 0x5E, 0x41, 0x00, 0xB0, 0x08, 0x00, 0x00, 0x00, 0x70, 0x07 ; 3DBF .....A^A......p.
        db 0x07, 0x0F, 0x70, 0x1F, 0x1F, 0x1E, 0x6B, 0x41, 0xA0, 0x42, 0x5E, 0x41, 0x00, 0xB0, 0x08, 0x00 ; 3DCF ..p...kA.B^A....
        db 0x00, 0x00, 0x70, 0x07, 0x07, 0x0F, 0x70, 0x1F, 0x1F, 0x1E, 0x6B, 0x41, 0xCF, 0x42, 0x5E, 0x41 ; 3DDF ..p...p...kA.B^A
        db 0x00, 0xB0, 0x09, 0x00, 0x00, 0x00, 0x70, 0x07, 0x07, 0x0F, 0x70, 0x4F, 0x4F, 0x4F, 0x77, 0x41 ; 3DEF ......p...pOOOwA
        db 0xDC, 0x44, 0x5E, 0x41, 0x00, 0xF0, 0x00, 0x00, 0x00, 0x00, 0x70, 0x07, 0x07, 0x0F, 0x70, 0x1F ; 3DFF .D^A......p...p.
        db 0x1F, 0x1E, 0x00, 0x00, 0x03, 0x43, 0x5E, 0x41, 0x00, 0x00, 0x02, 0x3F, 0x13, 0x0E, 0x70, 0x07 ; 3E0F .....C^A...?..p.
        db 0x07, 0x0F, 0x70, 0x4F, 0x4F, 0x4F, 0x00, 0x00, 0x27, 0x43, 0x5E, 0x41, 0x00, 0xB0, 0x15, 0x00 ; 3E1F ..pOOO..'C^A....
        db 0x00, 0x00, 0x70, 0x07, 0x07, 0x0F, 0x70, 0x1F, 0x1F, 0x1E, 0x6B, 0x41, 0xCF, 0x42, 0x5E, 0x41 ; 3E2F ..p...p...kA.B^A
        db 0x00, 0xB8, 0x00, 0x00, 0x00, 0x00, 0x70, 0x07, 0x07, 0x0F, 0x70, 0x4F, 0x4F, 0x4F, 0x77, 0x41 ; 3E3F ......p...pOOOwA
        db 0x0F, 0x45, 0x5E, 0x41 ; 3E4F .E^A

; 10 string-record pointers for std_show_error codes 0-9.
std_error_msg_ids:
        db 0x7A, 0x43, 0x8B, 0x43, 0xAF, 0x43, 0xD6, 0x43, 0xFB, 0x43, 0x2A, 0x44, 0x57, 0x44, 0x78, 0x44 ; 3E53 zC.C.C.C.C*DWDxD
        db 0x95, 0x44, 0xC1, 0x44 ; 3E63 .D.D

; std_draw_frame then the box record 3DC7 ('Saving to disk').
std_draw_saving_box:
        call std_draw_frame                      ; 3E67
        push cs                                  ; 3E6A
        pop es                                   ; 3E6B
        mov di, 0x3dc7                           ; 3E6C
        call draw_box_record                     ; 3E6F
        ret                                      ; 3E72

; std_draw_frame then box record 3DDB ('Restoring').
std_draw_restoring_box:
        call std_draw_frame                      ; 3E73
        mov di, 0x3ddb                           ; 3E76
        call draw_box_record                     ; 3E79
        ret                                      ; 3E7C

; AL = error code 0-9 (>= 10 -> 0): draws box record 3DEF and the message from std_error_msg_ids[AL]; prints it centred.
std_show_error:
        mov ah, 0                                ; 3E7D
        cmp al, 0xa                              ; 3E7F
        jb short loc_3E85                        ; 3E81
        mov al, 0                                ; 3E83

loc_3E85:
        push cs                                  ; 3E85
        pop es                                   ; 3E86
        mov di, 0x3def                           ; 3E87
        call draw_box_record                     ; 3E8A
        db 0x8B, 0xD8                            ; 3E8D  mov bx, ax
        shl bx, 1                                ; 3E8F
        mov di, word [cs:bx + 0x3e53]            ; 3E91
        call find_string_record                  ; 3E96
        call strlen_es_di                        ; 3E99
        call centre_col                          ; 3E9C
        mov dh, byte [cs:0x3df1]                 ; 3E9F
        inc dh                                   ; 3EA4
        call put_string_xy                       ; 3EA6
        ret                                      ; 3EA9

; Box record 3E03.
std_draw_done_box:
        call std_fill_screen                     ; 3EAA
        push cs                                  ; 3EAD
        pop es                                   ; 3EAE
        mov di, 0x3e03                           ; 3EAF
        call draw_box_record                     ; 3EB2
        ret                                      ; 3EB5

; Cursor off, attribute fill, frame records 3D9F/3DB3, the 'stage' string list 41E3 (id 30h), zeroes the six progress counters at SS:0000-000A and draws them.
std_draw_frame:
        call crtc_cursor_off                     ; 3EB6
        call std_fill_screen                     ; 3EB9
        mov di, 0x3d9f                           ; 3EBC
        call draw_box_record                     ; 3EBF
        mov di, 0x3db3                           ; 3EC2
        call draw_box_record                     ; 3EC5
        mov di, 0x3db3                           ; 3EC8
        call box_geometry                        ; 3ECB
        mov di, 0x41e3                           ; 3ECE
        call find_string_record                  ; 3ED1
        mov al, 0x30                             ; 3ED4  -> api_entry_30_power_meter
        call strchr_es_di                        ; 3ED6
        inc cl                                   ; 3ED9
        db 0x02, 0xCA                            ; 3EDB  add cl, dl
        mov byte [ss:0xb], cl                    ; 3EDD
        db 0x33, 0xC0                            ; 3EE2  xor ax, ax
        mov byte [ss:0], al                      ; 3EE4
        mov word [ss:1], ax                      ; 3EE8
        mov word [ss:5], ax                      ; 3EEC
        mov word [ss:3], ax                      ; 3EF0
        mov word [ss:7], ax                      ; 3EF4
        mov word [ss:9], ax                      ; 3EF8
        db 0x8B, 0xC8                            ; 3EFC  mov cx, ax
        call std_progress_update                 ; 3EFE
        ret                                      ; 3F01

; Fills the whole screen with attribute 07h (mono) / 03h from record 415E.
std_fill_screen:
        push cs                                  ; 3F02
        pop es                                   ; 3F03
        mov di, 0x415e                           ; 3F04
        call find_string_record                  ; 3F07
        mov al, byte [es:di + 8]                 ; 3F0A
        mov ah, 3                                ; 3F0E  -> init_stub
        call is_color_text                       ; 3F10
        je short loc_3F17                        ; 3F13
        mov ah, 7                                ; 3F15

loc_3F17:
        call fill_screen_attr                    ; 3F17
        ret                                      ; 3F1A

; SS:0000 := AL (0 base RAM, 1 extended, 2 SMRAM, 3 upper memory).
std_set_stage:
        mov byte [ss:0], al                      ; 3F1B
        ret                                      ; 3F1F

; Word offsets 1,3,5,7 of the per-stage sector counters in SS:.
std_stage_counter_offsets:
; [data] std_stage_counter_offsets
        db 0x01, 0x00, 0x03, 0x00, 0x05, 0x00, 0x07, 0x00 ; 3F20 ........

; Adds CL sectors to the counter of the current stage and to the total (SS:0009); prints both with word_to_decimal_padded at the row from record 3DB3.
std_progress_update:
        pusha                                    ; 3F28
        push es                                  ; 3F29
        db 0x33, 0xC0                            ; 3F2A  xor ax, ax
        db 0x8A, 0xC1                            ; 3F2C  mov al, cl
        mov bh, 0                                ; 3F2E
        mov bl, byte [ss:0]                      ; 3F30
        db 0x8B, 0xCB                            ; 3F35  mov cx, bx
        shl bx, 1                                ; 3F37
        mov bx, word [cs:bx + 0x3f20]            ; 3F39
        add word [ss:bx], ax                     ; 3F3E
        add word [ss:9], ax                      ; 3F41
        mov ax, 6                                ; 3F46
        call alloca_es_di                        ; 3F49
        mov ax, word [ss:bx]                     ; 3F4C
        mov bl, 0x20                             ; 3F4F
        call word_to_decimal_padded              ; 3F51
        mov dh, byte [ss:0]                      ; 3F54
        add dh, byte [cs:0x3db5]                 ; 3F59
        inc dh                                   ; 3F5E
        mov dl, byte [ss:0xb]                    ; 3F60
        mov cx, 5                                ; 3F65
        call put_string_xy                       ; 3F68
        mov ax, word [ss:9]                      ; 3F6B
        call word_to_decimal_padded              ; 3F6F
        mov dh, byte [cs:0x3db5]                 ; 3F72
        add dh, 6                                ; 3F77
        call put_string_xy                       ; 3F7A
        leave                                    ; 3F7D
        pop es                                   ; 3F7E
        popa                                     ; 3F7F
        ret                                      ; 3F80

; 16 SMM state-save offsets (ACh CS, A0h.., 9Ch, 98h, 94h, 90h, 0Ah.., 32h, 30h, 8Ch) followed by DEBUG-style flag mnemonics: bit 0Bh 'NV/OV', 0Ah 'UP/DN', 09h 'DI/EI', 07h 'PL/NG', 06h 'NZ/ZR', 04h 'NA/AC', 02h 'PO/PE', 00h 'NC/CY'.
debug_flag_table:
; [data] debug_flag_table
        db 0xAC, 0xA0, 0xA8, 0xA4, 0x9C, 0x98, 0x94, 0x90, 0x0A, 0x08, 0x06, 0x04, 0x02, 0x32, 0x30, 0x8C ; 3F81 .............20.
        db 0x0B, 0x4E, 0x56, 0x00, 0x4F, 0x56, 0x00, 0x0A, 0x55, 0x50, 0x00, 0x44, 0x4E, 0x00, 0x09, 0x44 ; 3F91 .NV.OV..UP.DN..D
        db 0x49, 0x00, 0x45, 0x49, 0x00, 0x07, 0x50, 0x4C, 0x00, 0x4E, 0x47, 0x00, 0x06, 0x4E, 0x5A, 0x00 ; 3FA1 I.EI..PL.NG..NZ.
        db 0x5A, 0x52, 0x00, 0x04, 0x4E, 0x41, 0x00, 0x41, 0x43, 0x00, 0x02, 0x50, 0x4F, 0x00, 0x50, 0x45 ; 3FB1 ZR..NA.AC..PO.PE
        db 0x00, 0x00, 0x4E, 0x43, 0x00, 0x43, 0x59, 0x00 ; 3FC1 ..NC.CY.

; Far-callable (RETF) register dump: pushad/pushfd, draws box record 3E17, prints the saved registers from the stack frame as hex and the flags with the DEBUG mnemonics from debug_flag_table. Development aid left in the ROM.
debug_register_dump:
        pushad                                   ; 3FC9
        pushfd                                   ; 3FCB
        push ds                                  ; 3FCD
        push es                                  ; 3FCE
        push fs                                  ; 3FCF
        push gs                                  ; 3FD1
        push ss                                  ; 3FD3
        push cs                                  ; 3FD4
        pop es                                   ; 3FD5
        mov di, 0x3e17                           ; 3FD6
        call draw_box_record                     ; 3FD9
        mov ax, 0xa                              ; 3FDC
        call alloca_es_di                        ; 3FDF
        push word [bp + 0x30]                    ; 3FE2
        sub word [bp + 0x30], 5                  ; 3FE5
        add word [bp + 0x1c], 4                  ; 3FE9
        mov dh, byte [cs:0x3e19]                 ; 3FED
        mov dl, byte [cs:0x3e1a]                 ; 3FF2
        add dx, 0x106                            ; 3FF7
        mov cx, 0x10                             ; 3FFB  -> api_entry_10
        mov bx, 0x3f81                           ; 3FFE

loc_4001:
        push cx                                  ; 4001
        movzx si, byte [cs:bx]                   ; 4002
        btr si, 7                                ; 4006
        lea si, [bp + si]                        ; 400A
        mov eax, dword [ss:si]                   ; 400C
        push 0x4020                              ; 4010  -> debug_register_dump_loop
        mov cx, 8                                ; 4013
        jb near hex_dword_to_ascii               ; 4016
        mov cx, 4                                ; 401A
        jmp near hex_word_to_ascii               ; 401D

; Continuation of debug_register_dump: prints the flag mnemonics and register rows.
debug_register_dump_loop:
        call put_string_xy                       ; 4020
        inc dh                                   ; 4023
        inc bx                                   ; 4025
        pop cx                                   ; 4026
        loop loc_4001                            ; 4027
        push cs                                  ; 4029
        pop es                                   ; 402A
        sub dl, 4                                ; 402B
        add dh, 1                                ; 402E
        mov bx, 0x3f91                           ; 4031
        mov cx, 2                                ; 4034

loc_4037:
        push cx                                  ; 4037
        push dx                                  ; 4038
        mov cx, 4                                ; 4039

loc_403C:
        movzx esi, byte [cs:bx]                  ; 403C
        lea di, [bx + 1]                         ; 4041
        bt dword [bp + 0xc], esi                 ; 4044
        jae short loc_404E                       ; 4049
        add di, 3                                ; 404B

loc_404E:
        push cx                                  ; 404E
        mov cx, 2                                ; 404F
        call put_string_xy                       ; 4052
        pop cx                                   ; 4055
        add dx, 3                                ; 4056
        add bx, 7                                ; 4059
        loop loc_403C                            ; 405C
        pop dx                                   ; 405E
        pop cx                                   ; 405F
        inc dh                                   ; 4060
        loop loc_4037                            ; 4062
        pop word [bp + 0x30]                     ; 4064
        leave                                    ; 4067
        add sp, 6                                ; 4068
        pop es                                   ; 406B
        pop ds                                   ; 406C
        popfd                                    ; 406D
        popad                                    ; 406F
        retf                                     ; 4071

; Draws box record 3E2B.
draw_box_3E2B:
        pusha                                    ; 4072
        push ds                                  ; 4073
        push es                                  ; 4074
        push cs                                  ; 4075
        pop es                                   ; 4076
        mov di, 0x3e2b                           ; 4077
        call draw_box_record                     ; 407A
        pop es                                   ; 407D
        pop ds                                   ; 407E
        popa                                     ; 407F
        ret                                      ; 4080

; AH = attribute: fills rows x cols with AX.
fill_screen_attr:
        push cx                                  ; 4081
        push dx                                  ; 4082
        push ax                                  ; 4083
        call get_screen_dims                     ; 4084
        db 0x8A, 0xC1                            ; 4087  mov al, cl
        mul ch                                   ; 4089
        db 0x8B, 0xC8                            ; 408B  mov cx, ax
        pop ax                                   ; 408D
        db 0x33, 0xD2                            ; 408E  xor dx, dx
        call fill_words_xy                       ; 4090
        pop dx                                   ; 4093
        pop cx                                   ; 4094
        ret                                      ; 4095

; Character AL at row DH col DL.
put_char_xy:
        push di                                  ; 4096
        push es                                  ; 4097
        call video_addr_es_di                    ; 4098
        stosb                                    ; 409B
        pop es                                   ; 409C
        pop di                                   ; 409D
        ret                                      ; 409E

; Attribute AH at row DH col DL.
put_attr_xy:
        push di                                  ; 409F
        push es                                  ; 40A0
        call video_addr_es_di                    ; 40A1
        mov byte [es:di + 1], ah                 ; 40A4
        pop es                                   ; 40A8
        pop di                                   ; 40A9
        ret                                      ; 40AA

; CX copies of AX (char+attr) from row DH col DL.
fill_words_xy:
        push cx                                  ; 40AB
        push di                                  ; 40AC
        push es                                  ; 40AD
        cld                                      ; 40AE
        call video_addr_es_di                    ; 40AF
        rep stosw                                ; 40B2
        pop es                                   ; 40B4
        pop di                                   ; 40B5
        pop cx                                   ; 40B6
        ret                                      ; 40B7

; CX characters from ES:DI with attribute AH.
put_string_attr_xy:
        cld                                      ; 40B8
        pusha                                    ; 40B9
        push ds                                  ; 40BA
        push es                                  ; 40BB
        call ds_si_from_es_di                    ; 40BC
        call video_addr_es_di                    ; 40BF
        db 0x8A, 0xC4                            ; 40C2  mov al, ah

loc_40C4:
        movsb                                    ; 40C4
        stosb                                    ; 40C5
        loop loc_40C4                            ; 40C6
        pop es                                   ; 40C8
        pop ds                                   ; 40C9
        popa                                     ; 40CA
        ret                                      ; 40CB

; CX characters from ES:DI, attributes untouched.
put_string_xy:
        cld                                      ; 40CC
        pusha                                    ; 40CD
        push ds                                  ; 40CE
        push es                                  ; 40CF
        call ds_si_from_es_di                    ; 40D0
        call video_addr_es_di                    ; 40D3

loc_40D6:
        movsb                                    ; 40D6
        inc di                                   ; 40D7
        loop loc_40D6                            ; 40D8
        pop es                                   ; 40DA
        pop ds                                   ; 40DB
        popa                                     ; 40DC
        ret                                      ; 40DD

; CH rows x CL columns of AX from DH/DL.
fill_rect:
        push cx                                  ; 40DE
        push dx                                  ; 40DF

loc_40E0:
        push cx                                  ; 40E0
        mov ch, 0                                ; 40E1
        call fill_words_xy                       ; 40E3
        inc dh                                   ; 40E6
        pop cx                                   ; 40E8
        dec ch                                   ; 40E9
        jne short loc_40E0                       ; 40EB
        pop dx                                   ; 40ED
        pop cx                                   ; 40EE
        ret                                      ; 40EF

; CRTC 0Ah := 1Fh (3D4h, or 3B4h in mode 7).
crtc_cursor_off:
        push ax                                  ; 40F0
        push dx                                  ; 40F1
        mov ax, 0x1f0a                           ; 40F2
        mov dx, 0x3d4                            ; 40F5
        call is_video_mode_3                     ; 40F8
        je short loc_40FF                        ; 40FB
        mov dh, 0x3b                             ; 40FD

loc_40FF:
        out dx, ax                               ; 40FF
        pop dx                                   ; 4100
        pop ax                                   ; 4101
        ret                                      ; 4102

; ZF = (40:49 == 3).
is_video_mode_3:
        push ds                                  ; 4103
        push 0                                   ; 4104
        pop ds                                   ; 4106
        cmp byte [0x400 + bda.video_mode], 3     ; 4107  bda.video_mode
        pop ds                                   ; 410C
        ret                                      ; 410D

; ZF when 40:89 bit 2 is clear and the mode is 3 (colour text); used to pick the colour attribute set of a box record.
is_color_text:
        push ds                                  ; 410E
        push 0                                   ; 410F
        pop ds                                   ; 4111
        test byte [0x400 + bda.video_flags_89], 4 ; 4112  bda.video_flags_89
        jne short loc_411C                       ; 4117
        call is_video_mode_3                     ; 4119

loc_411C:
        pop ds                                   ; 411C
        ret                                      ; 411D

; CL = columns (40:4A), CH = rows (40:84 + 1).
get_screen_dims:
        push ds                                  ; 411E
        push 0                                   ; 411F
        pop ds                                   ; 4121
        mov cx, word [0x400 + bda.video_columns] ; 4122  bda.video_columns
        mov ch, byte [0x400 + bda.video_rows_minus1] ; 4126  bda.video_rows_minus1
        inc ch                                   ; 412A
        pop ds                                   ; 412C
        ret                                      ; 412D

; ES:DI = B800h (B000h unless mode 3) : (row DH x cols + col DL) x 2 + 40:4E.
video_addr_es_di:
        push ax                                  ; 412E
        push bx                                  ; 412F
        push dx                                  ; 4130
        db 0x33, 0xC0                            ; 4131  xor ax, ax
        mov es, ax                               ; 4133
        db 0x8B, 0xDA                            ; 4135  mov bx, dx
        xchg bh, al                              ; 4137
        mul word [es:0x400 + bda.video_columns]  ; 4139  bda.video_columns
        db 0x03, 0xC3                            ; 413E  add ax, bx
        shl ax, 1                                ; 4140
        add ax, word [es:0x400 + bda.video_page_offset] ; 4142  bda.video_page_offset
        db 0x8B, 0xF8                            ; 4147  mov di, ax
        mov ax, 0xb800                           ; 4149
        call is_video_mode_3                     ; 414C
        je short loc_4153                        ; 414F
        mov ah, 0xb0                             ; 4151

loc_4153:
        mov es, ax                               ; 4153
        pop dx                                   ; 4155
        pop bx                                   ; 4156
        pop ax                                   ; 4157
        ret                                      ; 4158

; DS:SI := ES:DI.
ds_si_from_es_di:
        push es                                  ; 4159
        pop ds                                   ; 415A
        db 0x8B, 0xF7                            ; 415B  mov si, di
        ret                                      ; 415D

