; Allocates AX (rounded even) bytes on the caller's stack and returns ES:DI -> buffer (pops its own return address first).
alloca_es_di:
        pop di                                   ; 45EE
        push bp                                  ; 45EF
        db 0x8B, 0xEC                            ; 45F0  mov bp, sp
        inc ax                                   ; 45F2
        and al, 0xfe                             ; 45F3
        db 0x2B, 0xE0                            ; 45F5  sub sp, ax
        push di                                  ; 45F7
        push ss                                  ; 45F8
        pop es                                   ; 45F9
        db 0x8B, 0xFC                            ; 45FA  mov di, sp
        inc di                                   ; 45FC
        inc di                                   ; 45FD
        ret                                      ; 45FE

; CX = length of the NUL-terminated string at ES:DI.
strlen_es_di:
        cld                                      ; 45FF
        push ax                                  ; 4600
        push di                                  ; 4601
        db 0x33, 0xC0                            ; 4602  xor ax, ax
        mov cx, 0xffff                           ; 4604
        repne scasb                              ; 4607
        not cx                                   ; 4609
        dec cx                                   ; 460B
        pop di                                   ; 460C
        pop ax                                   ; 460D
        ret                                      ; 460E

; CX = number of NUL-terminated strings up to an empty one, BX = longest.
count_lines_max_len:
        push ax                                  ; 460F
        push di                                  ; 4610
        db 0x33, 0xC0                            ; 4611  xor ax, ax
        db 0x33, 0xDB                            ; 4613  xor bx, bx

loc_4615:
        call strlen_es_di                        ; 4615
        jcxz loc_4626                            ; 4618
        inc ax                                   ; 461A
        db 0x03, 0xF9                            ; 461B  add di, cx
        inc di                                   ; 461D
        db 0x3B, 0xCB                            ; 461E  cmp cx, bx
        jbe short loc_4615                       ; 4620
        db 0x8B, 0xD9                            ; 4622  mov bx, cx
        jmp short loc_4615                       ; 4624

loc_4626:
        db 0x8B, 0xC8                            ; 4626  mov cx, ax
        pop di                                   ; 4628
        pop ax                                   ; 4629
        ret                                      ; 462A

; CX = index of AL in the string at ES:DI.
strchr_es_di:
        cld                                      ; 462B
        push di                                  ; 462C
        db 0x33, 0xC9                            ; 462D  xor cx, cx

loc_462F:
        cmp byte [es:di], 0                      ; 462F
        je short loc_463B                        ; 4633
        scasb                                    ; 4635
        je short loc_463D                        ; 4636
        inc cx                                   ; 4638
        jmp short loc_462F                       ; 4639

loc_463B:
        db 0x0B, 0xE4                            ; 463B  or sp, sp

loc_463D:
        pop di                                   ; 463D
        ret                                      ; 463E

; AL -> two hex digits + NUL at ES:DI.
hex_byte_to_ascii:
        push ax                                  ; 463F
        push di                                  ; 4640
        cld                                      ; 4641
        db 0x8A, 0xE0                            ; 4642  mov ah, al
        shr al, 4                                ; 4644
        add al, 0x90                             ; 4647
        daa                                      ; 4649
        adc al, 0x40                             ; 464A
        daa                                      ; 464C
        stosb                                    ; 464D
        db 0x8A, 0xC4                            ; 464E  mov al, ah
        and al, 0xf                              ; 4650
        add al, 0x90                             ; 4652
        daa                                      ; 4654
        adc al, 0x40                             ; 4655
        daa                                      ; 4657
        stosb                                    ; 4658
        db 0x32, 0xC0                            ; 4659  xor al, al
        stosb                                    ; 465B
        pop di                                   ; 465C
        pop ax                                   ; 465D
        ret                                      ; 465E

; AX -> 4 hex digits at ES:DI (hex_byte_to_ascii twice).
hex_word_to_ascii:
        push di                                  ; 465F
        xchg al, ah                              ; 4660
        call hex_byte_to_ascii                   ; 4662
        inc di                                   ; 4665
        inc di                                   ; 4666
        xchg al, ah                              ; 4667
        call hex_byte_to_ascii                   ; 4669
        pop di                                   ; 466C
        ret                                      ; 466D

; EAX -> 8 hex digits at ES:DI.
hex_dword_to_ascii:
        push di                                  ; 466E
        ror eax, 0x10                            ; 466F
        call hex_word_to_ascii                   ; 4673
        add di, 4                                ; 4676
        ror eax, 0x10                            ; 4679
        call hex_word_to_ascii                   ; 467D
        pop di                                   ; 4680
        ret                                      ; 4681

; AH -> right-aligned decimal (2 pad chars AL) at ES:DI.
byte_to_decimal:
        push ax                                  ; 4682
        push cx                                  ; 4683
        push di                                  ; 4684
        cld                                      ; 4685
        mov cx, 2                                ; 4686
        xchg al, ah                              ; 4689
        rep stosb                                ; 468B
        dec di                                   ; 468D
        dec di                                   ; 468E
        db 0x0A, 0xC0                            ; 468F  or al, al
        je short loc_469F                        ; 4691
        cmp ah, 0x64                             ; 4693
        jae short loc_469F                       ; 4696
