        db 0x8A, 0xD3                            ; 5AF5  mov dl, bl
        pop esi                                  ; 5AF7
        pop bx                                   ; 5AF9
        pop ax                                   ; 5AFA
        ret                                      ; 5AFB

; Validate the good-space-map sector at SS:8D: dword signature 54 69 6D 4F (TimO), byte 91 == 0, dword 95 == 0, and the 16-bit sum of the following FCh words must equal ~word 93. AX = 6 (map missing) or 7 (map corrupted) on failure.
std_check_space_map:
        push bp                                  ; 5AFC
        push cx                                  ; 5AFD
        cmp dword [ss:0x8d], 0x4f6d6954          ; 5AFE
        mov ax, 6                                ; 5B08
        jne short loc_5B42                       ; 5B0B
        mov ax, 7                                ; 5B0D
        cmp byte [ss:0x91], 0                    ; 5B10
        jne short loc_5B42                       ; 5B16
        cmp dword [ss:0x95], 0                   ; 5B18
        jne short loc_5B42                       ; 5B1F
        db 0x33, 0xC0                            ; 5B21  xor ax, ax
        mov bp, 0x95                             ; 5B23
        mov cx, 0xfc                             ; 5B26

loc_5B29:
        add ax, word [bp]                        ; 5B29
        add bp, 2                                ; 5B2C
        loop loc_5B29                            ; 5B2F
        not ax                                   ; 5B31
        cmp word [ss:0x93], ax                   ; 5B33
        mov ax, 7                                ; 5B38
        jne short loc_5B42                       ; 5B3B
        db 0x33, 0xC0                            ; 5B3D  xor ax, ax
        pop cx                                   ; 5B3F
        pop bp                                   ; 5B40
        ret                                      ; 5B41

loc_5B42:
        stc                                      ; 5B42
        pop cx                                   ; 5B43
        pop bp                                   ; 5B44
        ret                                      ; 5B45

; Reverses the order of the used entries of the space map at SS:0095 (up to 3Fh entries, FFFFFFFF = unused).
std_space_map_reverse:
        push eax                                 ; 5B46
        push bx                                  ; 5B48
        push cx                                  ; 5B49
        push si                                  ; 5B4A
        push ds                                  ; 5B4B
        mov ax, ss                               ; 5B4C
        mov ds, ax                               ; 5B4E
        mov cx, 0x3f                             ; 5B50
        mov bx, 0x8d                             ; 5B53

loc_5B56:
        add bx, 8                                ; 5B56
        cmp dword [bx], -1                       ; 5B59
        loopne loc_5B56                          ; 5B5D
        jne short loc_5B64                       ; 5B5F
        inc cx                                   ; 5B61
        neg cx                                   ; 5B62

loc_5B64:
        add cx, 0x3f                             ; 5B64
        shr cx, 1                                ; 5B67
        je short loc_5B8E                        ; 5B69
        sub bx, 8                                ; 5B6B
        mov si, 0x95                             ; 5B6E

loc_5B71:
        mov eax, dword [si]                      ; 5B71
        xchg dword [bx], eax                     ; 5B74
        mov dword [si], eax                      ; 5B77
        mov eax, dword [si + 4]                  ; 5B7A
        xchg dword [bx + 4], eax                 ; 5B7E
        mov dword [si + 4], eax                  ; 5B82
        add si, 8                                ; 5B86
        sub bx, 8                                ; 5B89
        loop loc_5B71                            ; 5B8C

loc_5B8E:
        pop ds                                   ; 5B8E
        pop si                                   ; 5B8F
        pop cx                                   ; 5B90
        pop bx                                   ; 5B91
        pop eax                                  ; 5B92
        ret                                      ; 5B94

; POST EEh, std_show_error(AL), hang.
std_fatal:
        push ax                                  ; 5B95
        mov al, 0xee                             ; 5B96
        out 0x80, al                             ; 5B98  port 80h: POST diagnostic code
        pop ax                                   ; 5B9A
        call std_show_error                      ; 5B9B

loc_5B9E:
        jmp short loc_5B9E                       ; 5B9E

; IRQ14 handler during save/restore: 40:8E := FFh (disk interrupt flag), EOI both PICs, iret.
std_int76_stub:
        push ax                                  ; 5BA0
        push ds                                  ; 5BA1
        db 0x33, 0xC0                            ; 5BA2  xor ax, ax
        mov ds, ax                               ; 5BA4
        mov byte [0x400 + bda.hd_irq_flag], 0xff ; 5BA6  bda.hd_irq_flag
        mov al, 0x20                             ; 5BAB
        out 0xa0, al                             ; 5BAD  port A0h: PIC2 command
        out 0x20, al                             ; 5BAF  port 20h: PIC1 command
        pop ds                                   ; 5BB1
        pop ax                                   ; 5BB2
        iret                                     ; 5BB3

; Image position SS:0290 := 0, then std_disk_setup.
std_seek_0:
        mov dword [ss:0x290], 0                  ; 5BB4
        call std_disk_setup                      ; 5BBE
        ret                                      ; 5BC1

; SS:0290 := ECX (sector position in the image).
std_seek:
        mov dword [ss:0x290], ecx                ; 5BC2
        ret                                      ; 5BC8

; CL sectors at the current position into ES:DI; position advanced.
std_read_sectors:
        push esi                                 ; 5BC9
        push bx                                  ; 5BCB
        db 0x8B, 0xDF                            ; 5BCC  mov bx, di
        mov esi, dword [ss:0x290]                ; 5BCE
        call std_read_sectors_mapped             ; 5BD4
        movzx esi, cl                            ; 5BD7
        add dword [ss:0x290], esi                ; 5BDB
        pop bx                                   ; 5BE1
        pop esi                                  ; 5BE2
        ret                                      ; 5BE4

; CL sectors from ES:DI at the current position; position advanced.
std_write_sectors:
        push esi                                 ; 5BE5
        push bx                                  ; 5BE7
        db 0x8B, 0xDF                            ; 5BE8  mov bx, di
        mov esi, dword [ss:0x290]                ; 5BEA
        call std_write_sectors_mapped            ; 5BF0
        movzx esi, cl                            ; 5BF3
        add dword [ss:0x290], esi                ; 5BF7
        pop bx                                   ; 5BFD
        pop esi                                  ; 5BFE
        ret                                      ; 5C00
; [data] apm_pm32_entry_thunk (32-bit code) + pad
        db 0x00 ; 5C01 .

; 32-bit (USE32) code that capstone's 16-bit decoder cannot show: pushes the return 5C26h (pop si / pop ds / retf) and apm_dispatch_retf32 (04DCh), DS := CS+10h (data selector), RETF - the APM 32-bit protected-mode entry.
apm_pm32_entry_thunk:
        db 0x1E, 0x56, 0x0E, 0xBE, 0x26, 0x5C, 0x00, 0x00, 0x56, 0x66, 0x8C, 0xCE, 0x66, 0x83, 0xC6, 0x08 ; 5C02 .V..&\..Vf..f...
        db 0x66, 0x56, 0x66, 0xBE, 0xDC, 0x04, 0x66, 0x56, 0x66, 0x8C, 0xCE, 0x66, 0x83, 0xC6, 0x10, 0x66 ; 5C12 fVf...fVf..f...f
        db 0x8E, 0xDE, 0x66, 0xCB, 0x5E, 0x1F, 0xCB ; 5C22 ..f.^..

; 00h fill to the end of the 24 KB module (5C29-5FFF).
zero_fill_tail:
; [data] zero_fill_tail
        times 983 db 0x00                     ; 5C29 fill
